### Contoh

```python run
class Produk:
    def __init__(self, nama, harga, stok):
        self.nama = nama
        self.harga = harga
        self.stok = stok

    def __str__(self):
        return f"{self.nama} Rp{self.harga} (stok {self.stok})"

class Keranjang:
    def __init__(self):
        self.isi = []

    def tambah(self, produk, jumlah=1):
        if jumlah > produk.stok:
            raise ValueError(f"stok {produk.nama} kurang")
        self.isi.append((produk, jumlah))

    def total(self):
        return sum(p.harga * j for p, j in self.isi)

    def checkout(self):
        for p, j in self.isi:
            p.stok -= j
        bayar = self.total()
        self.isi = []
        return bayar

kopi = Produk("Kopi", 15000, 5)
gula = Produk("Gula", 12000, 2)
k = Keranjang()
k.tambah(kopi, 2)
k.tambah(gula)
try:
    k.tambah(gula, 10)
except ValueError as e:
    print("Ditolak:", e)
print("Total:", k.total())
print("Bayar:", k.checkout())
print(kopi)
print(gula)
```

Setiap class punya tanggung jawab yang jelas. Kalau aturan stok berubah, cukup ubah di satu tempat.

